class Solution {
    public int[][] construct2DArray(int[] original,int m,int n){
        if(original.length!=m*n)return new int[0][];
        int[][] answer=new int[m][n];
        for(int i=0;i<original.length;i++)answer[i/n][i%n]=original[i];
        return answer;
    }
}

code.kotlin:
class Solution {
    fun construct2DArray(original:IntArray,m:Int,n:Int):Array<IntArray>{
        if(original.size!=m*n)return emptyArray();
        return Array(m){
            row->IntArray(n){
                col->original[row*n+col]
            }
        }
    }
}

